#!/usr/bin/env bash
# Regenerate the VA-API and NVENC type bindings (`vaapi/sys.rs`, `nvenc/sys.rs`
# under moonshine-core's video pipeline). Types and constants only: both
# libraries are loaded at runtime, so building Pyroshine needs neither.
#
# Inputs: the system libva headers (/usr/include/va, libva 2.24 or newer) and
# nv-codec-headers n12.1.14.0 (MIT), downloaded and checked against a pinned
# SHA-256. Needs a Rust toolchain, libclang and network access for the
# pinned bindgen crate. Commit the regenerated files together.
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
pipeline="${root}/moonshine-core/src/session/stream/video/pipeline"
nv_version="n12.1.14.0"
nv_sha256="2fefaa227d2a3b4170797796425a59d1dd2ed5fd231db9b4244468ba327acd0b"
work="$(mktemp -d)"
trap 'rm -rf "${work}"' EXIT

curl -fsSL -o "${work}/nvh.tar.gz" \
  "https://github.com/FFmpeg/nv-codec-headers/archive/refs/tags/${nv_version}.tar.gz"
echo "${nv_sha256}  ${work}/nvh.tar.gz" | sha256sum --check --quiet
tar -xzf "${work}/nvh.tar.gz" -C "${work}"
nv_include="${work}/nv-codec-headers-${nv_version}/include"

mkdir -p "${work}/gen/src"
cat > "${work}/gen/Cargo.toml" <<'EOF'
[package]
name = "encoder-ffi-gen"
version = "0.0.0"
edition = "2021"

[dependencies]
bindgen = "=0.69.5"

[workspace]
EOF
cat > "${work}/gen/src/main.rs" <<'EOF'
use bindgen::{Builder, EnumVariation};

fn common(builder: Builder) -> Builder {
	builder
		.layout_tests(true)
		.derive_default(true)
		.derive_debug(false)
		.generate_comments(false)
		.default_enum_style(EnumVariation::Consts)
		.prepend_enum_name(false)
		.size_t_is_usize(true)
		.use_core()
		.blocklist_function(".*")
}

fn main() {
	let mut args = std::env::args().skip(1);
	let (out, nv_include) = (args.next().unwrap(), args.next().unwrap());
	common(Builder::default())
		.header_contents(
			"va_wrapper.h",
			"#include <va/va.h>\n#include <va/va_drm.h>\n#include <va/va_drmcommon.h>\n\
			 #include <va/va_enc_h264.h>\n#include <va/va_enc_hevc.h>\n#include <va/va_enc_av1.h>\n",
		)
		.allowlist_type(
			"VADisplay|VAStatus|VAProfile|VAEntrypoint|VAConfigAttrib|VAConfigAttribType|VAConfigID|\
			 VAContextID|VASurfaceID|VABufferID|VABufferType|VASurfaceAttrib|VASurfaceAttribType|\
			 VAGenericValue|VAGenericValueType|VADRMPRIMESurfaceDescriptor|VACodedBufferSegment|\
			 VAEncMiscParameterBuffer|VAEncMiscParameterType|VAEncMiscParameterRateControl|\
			 VAEncMiscParameterHRD|VAEncMiscParameterFrameRate|VAEncPackedHeaderParameterBuffer|\
			 VAEncPackedHeaderType|VAEncSequenceParameterBufferH264|VAEncPictureParameterBufferH264|\
			 VAEncSliceParameterBufferH264|VAPictureH264|VAEncSequenceParameterBufferHEVC|\
			 VAEncPictureParameterBufferHEVC|VAEncSliceParameterBufferHEVC|VAPictureHEVC|\
			 VAMessageCallback|VAConfigAttribValEncHEVCFeatures|VAConfigAttribValEncHEVCBlockSizes|\
			 VAEncSequenceParameterBufferAV1|VAEncPictureParameterBufferAV1|VAEncTileGroupBufferAV1|\
			 VAConfigAttribValEncAV1|VAConfigAttribValEncAV1Ext1|VAConfigAttribValEncAV1Ext2",
		)
		.allowlist_var(
			"VA_RT_FORMAT_.*|VA_FOURCC_.*|VA_RC_.*|VA_ENC_PACKED_HEADER_.*|VA_PICTURE_H264_.*|\
			 VA_PICTURE_HEVC_.*|VA_SURFACE_ATTRIB_.*|VA_EXPORT_SURFACE_.*|VA_STATUS_.*|VA_INVALID_.*|\
			 VA_PROGRESSIVE|VA_ATTRIB_NOT_SUPPORTED|VA_CODED_BUF_STATUS_.*|VA_TIMEOUT_INFINITE|\
			 VA_MAJOR_VERSION|VA_MINOR_VERSION",
		)
		.generate()
		.expect("libva bindings")
		.write_to_file(format!("{out}/va.rs"))
		.unwrap();
	common(Builder::default())
		.clang_arg(format!("-I{nv_include}"))
		.header_contents(
			"nv_wrapper.h",
			"#include <stdint.h>\n#include <ffnvcodec/dynlink_cuda.h>\n#include <ffnvcodec/nvEncodeAPI.h>\n",
		)
		.allowlist_type("NV_.*|_NV_.*|NVENC.*|PNV.*|GUID|_GUID|CU.*|tcu.*")
		.allowlist_var("NV_ENC_.*|NVENC.*|CU.*")
		// The headers' `static const GUID`s cannot be linked; mod.rs defines them.
		.blocklist_item("NV_ENC_.*_GUID")
		.generate()
		.expect("NVENC bindings")
		.write_to_file(format!("{out}/nv.rs"))
		.unwrap();
}
EOF
cargo run --quiet --release --manifest-path "${work}/gen/Cargo.toml" -- "${work}" "${nv_include}"

allows='#![allow(
	non_upper_case_globals,
	non_camel_case_types,
	non_snake_case,
	dead_code,
	unused_imports,
	unsafe_op_in_unsafe_fn,
	unnecessary_transmutes,
	clippy::all,
	clippy::pedantic
)]
'
{
  cat <<'EOF'
// Generated by bindgen 0.69.5 from the libva 2.24 headers (va.h, va_drm.h,
// va_drmcommon.h, va_enc_h264.h, va_enc_hevc.h, va_enc_av1.h; MIT license,
// Copyright Intel Corporation), types and constants only: libva is loaded at
// runtime (see `super::Va`). Regenerate with `scripts/generate-encoder-ffi.sh`;
// do not edit.
EOF
  printf '%s\n' "${allows}"
  cat "${work}/va.rs"
} > "${pipeline}/vaapi/sys.rs"
{
  cat <<EOF
// Generated by bindgen 0.69.5 from nv-codec-headers ${nv_version}
// (nvEncodeAPI.h, NVENC API 12.1, and dynlink_cuda.h; MIT license, Copyright
// NVIDIA Corporation), types and constants only: libcuda and libnvidia-encode
// are loaded at runtime (see \`super::Cuda\`, \`super::nvenc\`). Regenerate with
// \`scripts/generate-encoder-ffi.sh\`; do not edit.
EOF
  printf '%s\n' "${allows}"
  cat "${work}/nv.rs"
} > "${pipeline}/nvenc/sys.rs"
rustfmt --edition 2024 "${pipeline}/vaapi/sys.rs" "${pipeline}/nvenc/sys.rs"
